package dev.mesbase.web.controller.system;
import dev.mesbase.platform.web.EndpointAccess;import dev.mesbase.system.service.impl.SysAttachmentServiceImpl;import dev.mesbase.system.domain.SysAttachment;import dev.mesbase.common.core.domain.AjaxResult;import dev.mesbase.common.core.controller.BaseController;import dev.mesbase.common.core.page.TableDataInfo;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.http.*;
@RestController @RequestMapping("/api/platform/files") @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="mes.system.enabled",havingValue="true")
public class SystemFileController extends BaseController {
 private final SysAttachmentServiceImpl files;public SystemFileController(SysAttachmentServiceImpl files){this.files=files;}
 @GetMapping @EndpointAccess(value=EndpointAccess.Kind.AUTHENTICATED,permissionScope=EndpointAccess.PermissionScope.PLATFORM) public TableDataInfo list(@RequestParam String resource){startPage();return getDataTable(files.list(resource,dev.mesbase.platform.execution.FactoryContext.current().orElse(null)));}
 @PostMapping @EndpointAccess(value=EndpointAccess.Kind.AUTHENTICATED,permissionScope=EndpointAccess.PermissionScope.PLATFORM) public SysAttachment upload(@RequestParam String resource,@RequestParam MultipartFile file)throws java.io.IOException{return files.upload(resource,file.getOriginalFilename(),file.getContentType(),file.getInputStream(),dev.mesbase.platform.execution.FactoryContext.current().orElse(null));}
 @GetMapping("/{id}") @EndpointAccess(value=EndpointAccess.Kind.AUTHENTICATED,permissionScope=EndpointAccess.PermissionScope.PLATFORM) public SysAttachment metadata(@PathVariable String id,@RequestParam String resource){return files.metadata(id,resource,dev.mesbase.platform.execution.FactoryContext.current().orElse(null));}
 @DeleteMapping("/{id}") @EndpointAccess(value=EndpointAccess.Kind.AUTHENTICATED,permissionScope=EndpointAccess.PermissionScope.PLATFORM) public AjaxResult delete(@PathVariable String id,@RequestParam String resource)throws java.io.IOException{return toAjax(files.delete(id,resource,dev.mesbase.platform.execution.FactoryContext.current().orElse(null)));}
 @GetMapping("/{id}/content") @EndpointAccess(value=EndpointAccess.Kind.AUTHENTICATED,permissionScope=EndpointAccess.PermissionScope.PLATFORM) public ResponseEntity<byte[]> download(@PathVariable String id,@RequestParam String resource)throws java.io.IOException{var row=files.metadata(id,resource,dev.mesbase.platform.execution.FactoryContext.current().orElse(null));String type=SetSafe.image(row.getFileType())?row.getFileType():"application/octet-stream";return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).header("X-Content-Type-Options","nosniff").header("Content-Disposition",ContentDisposition.attachment().filename(row.getOrignalName(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(files.download(id,resource,dev.mesbase.platform.execution.FactoryContext.current().orElse(null)));}
 private static class SetSafe{static boolean image(String type){return java.util.Set.of("image/png","image/jpeg","image/gif","image/webp").contains(type);}}
}
